          "id": "code-ml-12-1-ch12_1_scratch",
          "title": "First-Principles NumPy: Audit Mercer PSD, Reproducing Property & Bukti Representer Theorem",
          "language": "python",
          "filename": "12_1_mercer_rkhs_representer_scratch.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(42)\nn, d = 60, 4\nX = rng.normal(0.0, 1.0, size=(n, d))\n\n# Jarak berpasangan L2 dan L1 secara vektorisasi\ndiff = X[:, None, :] - X[None, :, :]\nsq_dist = np.sum(diff ** 2, axis=-1)\nl2_dist = np.sqrt(np.maximum(sq_dist, 0.0))\nl1_dist = np.sum(np.abs(diff), axis=-1)\ndot = X @ X.T\n\n# 1. Uji Syarat Mercer PSD (eigenvalue minimum matriks Gram K >= 0) pada 5 kandidat kernel\nkernels = {\n    \"RBF (gamma=0.25)\": np.exp(-0.25 * sq_dist),\n    \"Matern nu=3/2 (l=1.5)\": (1.0 + np.sqrt(3.0) * l2_dist / 1.5) * np.exp(-np.sqrt(3.0) * l2_dist / 1.5),\n    \"Laplacian L1 (gamma=0.35)\": np.exp(-0.35 * l1_dist),\n    \"Polynomial (d=3, c0=1)\": (0.25 * dot + 1.0) ** 3,\n    \"Sigmoid / tanh (ILEGAL!)\": np.tanh(0.8 * dot - 1.2),\n}\n\nprint(\"=== Audit Syarat Mercer PSD (Positive Semi-Definite) pada Matriks Gram 60x60 ===\")\nprint(\"Kernel                    | lambda_min   | lambda_max | Status Mercer PSD\")\nprint(\"-\" * 76)\nfor name, K in kernels.items():\n    eigs = np.linalg.eigvalsh(0.5 * (K + K.T))\n    lmin, lmax = float(eigs[0]), float(eigs[-1])\n    status = \"VALID PSD\" if lmin >= -1e-10 else \"GAGAL! (Indefinite)\"\n    print(f\"{name:25s} | {lmin:12.6f} | {lmax:10.4f} | {status}\")\n\n# 2. Verifikasi Reproducing Property & Norma RKHS pada Kernel RBF\nK_rbf = kernels[\"RBF (gamma=0.25)\"]\ny = np.sin(X[:, 0]) + 0.5 * X[:, 1] ** 2 - 0.3 * X[:, 2]\nlam = 0.1\nalpha = np.linalg.solve(K_rbf + lam * np.eye(n), y)\n\n# Evaluasi f(x_i) = <f, k(., x_i)>_H = sum_j alpha_j k(x_j, x_i) = (K alpha)_i\nf_vals = K_rbf @ alpha\nrepro_err = float(np.max(np.abs(f_vals - np.array([alpha @ K_rbf[:, i] for i in range(n)]))))\nrkhs_norm_sq = float(alpha @ K_rbf @ alpha)\n\n# 3. Verifikasi Numerik Representer Theorem: tambahkan komponen ortogonal f_perp\n# Misal kita tambahkan 1 titik baru x_ext di luar data latih lalu proyeksi bagian ortogonalnya\nx_ext = np.array([[2.5, -1.8, 1.2, 0.9]])\nk_ext = np.exp(-0.25 * np.sum((X - x_ext) ** 2, axis=1))\nk_ext_self = 1.0\n# Vektor proyeksi di span data latih: beta_proj = K^-1 k_ext; sisa ortogonal punya norma^2 > 0\nbeta_proj = np.linalg.solve(K_rbf + 1e-10 * np.eye(n), k_ext)\nperp_norm_sq = float(k_ext_self - k_ext @ beta_proj)  # ||k(., x_ext) - proj||_H^2\n# Di setiap titik latih x_i, nilai f_perp(x_i) = k(x_ext, x_i) - k_ext^T K^-1 k_i = 0!\nf_perp_on_train = float(np.max(np.abs(k_ext - K_rbf @ beta_proj)))\n\nobj_opt = float(np.sum((y - f_vals) ** 2) + lam * rkhs_norm_sq)\nobj_with_perp = float(np.sum((y - f_vals) ** 2) + lam * (rkhs_norm_sq + 4.0 * perp_norm_sq))\n\nprint(\"-\" * 76)\nprint(\"=== Verifikasi Reproducing Property & Representer Theorem ===\")\nprint(f\"Max error Reproducing Property |f(x_i) - <f, k(.,x_i)>_H| : {repro_err:.2e}\")\nprint(f\"Norma RKHS kuadrat ||f*||_H^2 = alpha^T K alpha           : {rkhs_norm_sq:.4f}\")\nprint(f\"Max |f_perp(x_i)| pada seluruh titik latih                : {f_perp_on_train:.2e}\")\nprint(f\"Norma^2 komponen ortogonal ||f_perp||_H^2                 : {perp_norm_sq:.4f}\")\nprint(f\"Objektif Optimal J(f*) vs J(f* + 2 f_perp)                : {obj_opt:.4f} vs {obj_with_perp:.4f} (selalu naik!)\")",
          "expectedOutput": "=== Audit Syarat Mercer PSD (Positive Semi-Definite) pada Matriks Gram 60x60 ===\nKernel                    | lambda_min   | lambda_max | Status Mercer PSD\n----------------------------------------------------------------------------\nRBF (gamma=0.25)          |     0.000882 |    20.1910 | VALID PSD\nMatern nu=3/2 (l=1.5)     |     0.038031 |    18.7082 | VALID PSD\nLaplacian L1 (gamma=0.35) |     0.151955 |    17.5502 | VALID PSD\nPolynomial (d=3, c0=1)    |    -0.000000 |   132.4332 | VALID PSD\nSigmoid / tanh (ILEGAL!)  |   -35.298860 |    18.9818 | GAGAL! (Indefinite)\n----------------------------------------------------------------------------\n=== Verifikasi Reproducing Property & Representer Theorem ===\nMax error Reproducing Property |f(x_i) - <f, k(.,x_i)>_H| : 1.33e-15\nNorma RKHS kuadrat ||f*||_H^2 = alpha^T K alpha           : 14.8950\nMax |f_perp(x_i)| pada seluruh titik latih                : 2.90e-10\nNorma^2 komponen ortogonal ||f_perp||_H^2                 : 0.5519\nObjektif Optimal J(f*) vs J(f* + 2 f_perp)                : 1.8036 vs 2.0244 (selalu naik!)",
