          "filename": "12_1_gram_collapse_df_audit.py",
          "code": "import numpy as np\nfrom sklearn.kernel_ridge import KernelRidge\nfrom sklearn.metrics import r2_score\nfrom sklearn.metrics.pairwise import rbf_kernel\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(123)\nn_tr, n_te = 220, 300\n\n# 3 fitur nyata dengan skala heterogen ekstrem: [0.02, 1.0, 1500.0]\nZ_tr = rng.normal(0.0, 1.0, size=(n_tr, 3))\nZ_te = rng.normal(0.0, 1.0, size=(n_te, 3))\nscales = np.array([0.02, 1.0, 1500.0])\nX_tr_raw = Z_tr * scales\nX_te_raw = Z_te * scales\n\n# Sinyal sejati dikendalikan secara seimbang oleh ketiga fitur (non-linier)\ny_tr = np.sin(1.4 * Z_tr[:, 0]) + 0.8 * np.cos(1.2 * Z_tr[:, 1]) + 0.6 * Z_tr[:, 2] + rng.normal(0, 0.12, n_tr)\ny_te = np.sin(1.4 * Z_te[:, 0]) + 0.8 * np.cos(1.2 * Z_te[:, 1]) + 0.6 * Z_te[:, 2]\n\nscaler = StandardScaler().fit(X_tr_raw)\nX_tr_sc = scaler.transform(X_tr_raw)\nX_te_sc = scaler.transform(X_te_raw)\n\n# Hitung Median Heuristic gamma pada data terstandarisasi\nsq_sc = np.sum((X_tr_sc[:, None, :] - X_tr_sc[None, :, :]) ** 2, axis=-1)\nmed_sq = float(np.median(sq_sc[np.triu_indices(n_tr, k=1)]))\ngamma_med = 1.0 / (2.0 * med_sq)\n\nscenarios = [\n    (\"1. Tanpa Scaling (gamma=0.5) -> K ~ I\", X_tr_raw, X_te_raw, 0.5),\n    (\"2. Scaled, gamma=1e-4 terlalu kecil -> K ~ 11^T\", X_tr_sc, X_te_sc, 1e-4),\n    (\"3. Scaled, gamma=50.0 terlalu besar -> K ~ I\", X_tr_sc, X_te_sc, 50.0),\n    (f\"4. Scaled + Median Heuristic (gamma={gamma_med:.3f})\", X_tr_sc, X_te_sc, gamma_med),\n]\n\nlam = 0.05\nprint(\"=== Audit Kesehatan Matriks Gram: Off-Diag Mean, df(lambda), Cond & R^2 ===\")\nprint(\"Skenario                                       | OffDiag | df(lam) | Cond(K+lI) | R2 Uji\")\nprint(\"-\" * 92)\nfor label, Xtr, Xte, g in scenarios:\n    K = rbf_kernel(Xtr, Xtr, gamma=g)\n    off_mask = ~np.eye(n_tr, dtype=bool)\n    off_mean = float(np.mean(K[off_mask]))\n    eigs = np.maximum(np.linalg.eigvalsh(K), 0.0)\n    # Effective degrees of freedom: df(lambda) = sum_i eig_i / (eig_i + lambda)\n    df_lam = float(np.sum(eigs / (eigs + lam)))\n    cond_num = float((eigs[-1] + lam) / (eigs[0] + lam))\n    model = KernelRidge(alpha=lam, kernel=\"rbf\", gamma=g).fit(Xtr, y_tr)\n    r2 = float(r2_score(y_te, model.predict(Xte)))\n    print(f\"{label:46s} | {off_mean:7.4f} | {df_lam:7.1f} | {cond_num:10.1f} | {r2:6.3f}\")",
          "expectedOutput": "=== Audit Kesehatan Matriks Gram: Off-Diag Mean, df(lambda), Cond & R^2 ===\nSkenario                                       | OffDiag | df(lam) | Cond(K+lI) | R2 Uji\n--------------------------------------------------------------------------------------------\n1. Tanpa Scaling (gamma=0.5) -> K ~ I          |  0.0003 |   209.0 |       11.0 | -0.132\n2. Scaled, gamma=1e-4 terlalu kecil -> K ~ 11^T |  0.9994 |     2.4 |     4398.4 |  0.421\n3. Scaled, gamma=50.0 terlalu besar -> K ~ I   |  0.0003 |   209.3 |        5.3 | -0.031\n4. Scaled + Median Heuristic (gamma=0.105)     |  0.5887 |    27.8 |     2689.6 |  0.974",
