          "filename": "12_3_rff_cossin_streaming_audit.py",
          "code": "import numpy as np\nfrom sklearn.kernel_approximation import RBFSampler\nfrom sklearn.linear_model import SGDClassifier\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(323)\n\n# 1. Audit Varians Formulasi Cos-Shift vs Cos-Sin Paired pada anggaran dimensi D yang SAMA\nn_g, d_g = 150, 6\nX_g = rng.normal(0.0, 1.0, size=(n_g, d_g))\ngamma = 0.15\nK_exact = np.exp(-gamma * np.sum((X_g[:, None, :] - X_g[None, :, :]) ** 2, axis=-1))\n\nprint(\"=== Audit Varians RFF: Cos-Shift sqrt(2/D)cos(Wx+b) vs Cos-Sin Paired [cos, sin] ===\")\nprint(\"Dim D | Cos-Shift Rel-Frob | Cos-Sin Paired Rel-Frob | Pengurangan Error\")\nprint(\"-\" * 76)\nfor D in [64, 256, 512]:\n    err_shift, err_pair = [], []\n    for trial in range(15):\n        g_t = np.random.default_rng(1000 + trial)\n        # Cos-Shift: D vektor frekuensi acak + D fase seragam\n        W1 = g_t.normal(0.0, np.sqrt(2.0 * gamma), size=(d_g, D))\n        b1 = g_t.uniform(0.0, 2.0 * np.pi, size=D)\n        Z1 = np.sqrt(2.0 / D) * np.cos(X_g @ W1 + b1)\n        err_shift.append(float(np.linalg.norm(K_exact - Z1 @ Z1.T, \"fro\") / np.linalg.norm(K_exact, \"fro\")))\n\n        # Cos-Sin Paired: D/2 frekuensi menghasilkan D fitur [cos(Wx), sin(Wx)] tanpa derau fase b!\n        half = D // 2\n        W2 = g_t.normal(0.0, np.sqrt(2.0 * gamma), size=(d_g, half))\n        proj = X_g @ W2\n        Z2 = np.sqrt(1.0 / half) * np.hstack([np.cos(proj), np.sin(proj)])\n        err_pair.append(float(np.linalg.norm(K_exact - Z2 @ Z2.T, \"fro\") / np.linalg.norm(K_exact, \"fro\")))\n\n    m1, m2 = float(np.mean(err_shift)), float(np.mean(err_pair))\n    red = (m1 - m2) / m1 * 100.0\n    print(f\"{D:5d} | {m1:18.4f} | {m2:23.4f} | {red:+6.1f}% (Cos-Sin menang)\")\n\n# 2. Audit Out-of-Core Streaming Training: RBFSampler (Stateless) + SGDClassifier.partial_fit\nn_stream, batch_size, d_s = 10_000, 500, 5\nX_all = rng.normal(0.0, 1.0, size=(n_stream + 2000, d_s))\ny_all = (np.sin(X_all[:, 0] * X_all[:, 1]) + 0.5 * (X_all[:, 2] ** 2 - X_all[:, 3] ** 2) > 0.1).astype(int)\nX_str, y_str = X_all[:n_stream], y_all[:n_stream]\nX_val, y_val = X_all[n_stream:], y_all[n_stream:]\n\nscaler_s = StandardScaler()\nrff_s = RBFSampler(gamma=0.3, n_components=300, random_state=42)\n# Fit stateless RFF hanya butuh mengetahui d_s (jumlah fitur); scaler di-update secara incremental!\nscaler_s.partial_fit(X_str[:batch_size])\nrff_s.fit(np.zeros((1, d_s)))\nclf_s = SGDClassifier(loss=\"log_loss\", alpha=1e-4, random_state=42)\n\n# Streaming 2 pass (20 mini-batch per pass) dengan memori puncak konstan O(batch_size * D)\nfor epoch in range(2):\n    for start in range(0, n_stream, batch_size):\n        xb = X_str[start : start + batch_size]\n        yb = y_str[start : start + batch_size]\n        if epoch == 0 and start > 0:\n            scaler_s.partial_fit(xb)\n        zb = rff_s.transform(scaler_s.transform(xb))\n        clf_s.partial_fit(zb, yb, classes=np.array([0, 1]))\n\nval_acc = float(accuracy_score(y_val, clf_s.predict(rff_s.transform(scaler_s.transform(X_val)))))\npeak_batch_kb = (batch_size * 300 * 8) / 1024.0\nprint(\"-\" * 76)\nprint(\"=== Audit Streaming Out-of-Core: RBFSampler (Stateless) + partial_fit ===\")\nprint(f\"Total Sampel Stream: {n_stream} | Ukuran Batch: {batch_size} | Memori Z_batch Puncak: {peak_batch_kb:.1f} KB\")\nprint(f\"Akurasi Validasi Non-Linier (2 streaming pass): {val_acc*100:.2f}%\")",
          "expectedOutput": "=== Audit Varians RFF: Cos-Shift sqrt(2/D)cos(Wx+b) vs Cos-Sin Paired [cos, sin] ===\nDim D | Cos-Shift Rel-Frob | Cos-Sin Paired Rel-Frob | Pengurangan Error\n----------------------------------------------------------------------------\n   64 |             0.3771 |                  0.3674 |   +2.6% (Cos-Sin menang)\n  256 |             0.1845 |                  0.1789 |   +3.0% (Cos-Sin menang)\n  512 |             0.1347 |                  0.1233 |   +8.4% (Cos-Sin menang)\n----------------------------------------------------------------------------\n=== Audit Streaming Out-of-Core: RBFSampler (Stateless) + partial_fit ===\nTotal Sampel Stream: 10000 | Ukuran Batch: 500 | Memori Z_batch Puncak: 1171.9 KB\nAkurasi Validasi Non-Linier (2 streaming pass): 94.30%",
