          "language": "python",
          "filename": "12_4_nystrom_vs_rff_manifold_scratch.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(404)\n\n# Bangkitkan N=300 titik pada manifold halus berdimensi intrinsik 3D yang disematkan ke R^12\n# Struktur manifold menyebabkan spektrum nilai eigen matriks Gram K meluruh EKSPONENSIAL!\nn = 300\nlatent = rng.uniform(-2.0, 2.0, size=(n, 3))\nW_embed = rng.normal(0.0, 0.5, size=(3, 12))\nX = np.tanh(latent @ W_embed) + 0.03 * rng.normal(0.0, 1.0, size=(n, 12))\n\ngamma = 0.35\nsq_all = np.sum((X[:, None, :] - X[None, :, :]) ** 2, axis=-1)\nK_exact = np.exp(-gamma * sq_all)\nnorm_K = float(np.linalg.norm(K_exact, \"fro\"))\n\n# Cek seberapa cepat spektrum nilai eigen K meluruh\neigs_K = np.sort(np.maximum(np.linalg.eigvalsh(K_exact), 0.0))[::-1]\nenergy_top30 = float(np.sum(eigs_K[:30]) / np.sum(eigs_K))\n\ndef nystrom_features(X_data: np.ndarray, landmarks: np.ndarray, g: float, tol: float = 1e-10) -> np.ndarray:\n    K_nm = np.exp(-g * np.sum((X_data[:, None, :] - landmarks[None, :, :]) ** 2, axis=-1))\n    K_mm = np.exp(-g * np.sum((landmarks[:, None, :] - landmarks[None, :, :]) ** 2, axis=-1))\n    vals, vecs = np.linalg.eigh(0.5 * (K_mm + K_mm.T))\n    keep = vals > tol\n    inv_sqrt = 1.0 / np.sqrt(vals[keep])\n    return (K_nm @ vecs[:, keep]) * inv_sqrt[None, :]\n\ndef kmeans_pp_landmarks(X_data: np.ndarray, m: int, gen: np.random.Generator) -> np.ndarray:\n    # Seleksi landmark deterministik-probabilistik ala k-Means++ untuk cakupan manifold merata\n    chosen = [int(gen.integers(0, len(X_data)))]\n    min_d2 = np.sum((X_data - X_data[chosen[0]]) ** 2, axis=1)\n    for _ in range(1, m):\n        probs = min_d2 / np.sum(min_d2)\n        nxt = int(gen.choice(len(X_data), p=probs))\n        chosen.append(nxt)\n        d2_new = np.sum((X_data - X_data[nxt]) ** 2, axis=1)\n        min_d2 = np.minimum(min_d2, d2_new)\n    return X_data[chosen]\n\nprint(f\"=== Peluruhan Spektrum Manifold 3D di R^12: Top-30 Eigenvalue = {energy_top30*100:.2f}% Total Energi ===\")\nprint(\"m = D | RFF Rel-Frob | Nystrom-Uniform | Nystrom-kMeans++ | Min Eig (K - K_nys)\")\nprint(\"-\" * 82)\nfor m in [15, 30, 60, 120]:\n    # 1. RFF (data-independent)\n    W = rng.normal(0.0, np.sqrt(2.0 * gamma), size=(X.shape[1], m))\n    b = rng.uniform(0.0, 2.0 * np.pi, size=m)\n    Z_rff = np.sqrt(2.0 / m) * np.cos(X @ W + b)\n    err_rff = float(np.linalg.norm(K_exact - Z_rff @ Z_rff.T, \"fro\") / norm_K)\n\n    # 2. Nystrom Uniform Landmarks\n    idx_u = rng.choice(n, size=m, replace=False)\n    Z_nu = nystrom_features(X, X[idx_u], gamma)\n    K_nu = Z_nu @ Z_nu.T\n    err_nu = float(np.linalg.norm(K_exact - K_nu, \"fro\") / norm_K)\n\n    # 3. Nystrom k-Means++ Landmarks + cek PSD Schur Complement (K - K_tilde >= 0)\n    lm_kpp = kmeans_pp_landmarks(X, m, rng)\n    Z_nk = nystrom_features(X, lm_kpp, gamma)\n    K_nk = Z_nk @ Z_nk.T\n    err_nk = float(np.linalg.norm(K_exact - K_nk, \"fro\") / norm_K)\n    min_schur_eig = float(np.linalg.eigvalsh(0.5 * ((K_exact - K_nk) + (K_exact - K_nk).T))[0])\n\n    print(f\"{m:5d} | {err_rff:12.4f} | {err_nu:15.4f} | {err_nk:16.4f} | {min_schur_eig:+.2e} (PSD!)\")",
          "expectedOutput": "=== Peluruhan Spektrum Manifold 3D di R^12: Top-30 Eigenvalue = 95.03% Total Energi ===\nm = D | RFF Rel-Frob | Nystrom-Uniform | Nystrom-kMeans++ | Min Eig (K - K_nys)\n----------------------------------------------------------------------------------\n   15 |       0.8625 |          0.3007 |           0.2939 | -3.26e-15 (PSD!)\n   30 |       0.7372 |          0.1731 |           0.0955 | -5.48e-15 (PSD!)\n   60 |       0.5114 |          0.0499 |           0.0301 | -9.24e-15 (PSD!)\n  120 |       0.2802 |          0.0126 |           0.0050 | -2.31e-14 (PSD!)",
          "actualOutput": "=== Peluruhan Spektrum Manifold 3D di R^12: Top-30 Eigenvalue = 95.03% Total Energi ===\nm = D | RFF Rel-Frob | Nystrom-Uniform | Nystrom-kMeans++ | Min Eig (K - K_nys)\n----------------------------------------------------------------------------------\n   15 |       0.8625 |          0.3007 |           0.2939 | -3.26e-15 (PSD!)\n   30 |       0.7372 |          0.1731 |           0.0955 | -5.48e-15 (PSD!)\n   60 |       0.5114 |          0.0499 |           0.0301 | -9.24e-15 (PSD!)\n  120 |       0.2802 |          0.0126 |           0.0050 | -2.31e-14 (PSD!)",
